import sys
import uuid
from datetime import datetime

from sqlalchemy import DateTime, func
from sqlmodel import Field, SQLModel

# Deterministic constraint and index names, so autogenerated migrations are stable.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}

SQLModel.metadata.naming_convention = NAMING_CONVENTION

if sys.version_info >= (3, 14):
    # Time-ordered IDs keep B-tree inserts local.
    from uuid import uuid7 as new_uuid
else:
    from uuid import uuid4 as new_uuid


def utc_datetime_field(*, onupdate: bool = False) -> datetime:
    """A `timestamptz NOT NULL DEFAULT now()` column, optionally refreshed on every UPDATE."""
    kwargs: dict[str, object] = {"server_default": func.now(), "nullable": False}
    if onupdate:
        kwargs["onupdate"] = func.now()
    # Field() returns Any to satisfy every annotation; the server fills the value.
    return Field(default=None, sa_type=DateTime(timezone=True), sa_column_kwargs=kwargs)  # type: ignore[no-any-return]


class UUIDPrimaryKeyMixin(SQLModel):
    id: uuid.UUID = Field(default_factory=new_uuid, primary_key=True)


class TimestampMixin(SQLModel):
    created_at: datetime = utc_datetime_field()
    updated_at: datetime = utc_datetime_field(onupdate=True)

    # Read server-generated timestamps back with RETURNING after INSERT and UPDATE,
    # so they never need a lazy load (which async sessions don't allow).
    __mapper_args__ = {"eager_defaults": True}
